using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;
namespace NcnHelper {
public static class MemoryBackup {
 static readonly string[] Dirs={@"data\memory","sessions",@"data\characters",@"data\story",@"data\templates",@"data\routines"};
 static readonly string[] Files={@"data\world_state.json",@"data\voice_choices.json"};
 public static string Home{get{return Path.Combine(Core.Base,"Memory Backups");}}
 static bool Allowed(string rel){return Files.Any(x=>String.Equals(x,rel,StringComparison.OrdinalIgnoreCase))||Dirs.Any(x=>rel.StartsWith(x+"\\",StringComparison.OrdinalIgnoreCase));}
 static IEnumerable<string> Walk(string dir){if((File.GetAttributes(dir)&FileAttributes.ReparsePoint)!=0)throw new Exception("Memory folder is a link. Choose a regular installation.");foreach(var f in Directory.GetFiles(dir)){if(Path.GetFileName(f).StartsWith("__folder_managed"))continue;if((File.GetAttributes(f)&FileAttributes.ReparsePoint)!=0)throw new Exception("Memory file is a symbolic link.");yield return f;}foreach(var d in Directory.GetDirectories(dir))foreach(var f in Walk(d))yield return f;}
 public static string Create(string game){Core.GameClosed();Core.ValidateRoot(game);string mod=Core.Mod(game);var sources=new List<string>();foreach(var d in Dirs){string p=Path.Combine(mod,d);if(Directory.Exists(p))sources.AddRange(Walk(p));}foreach(var f in Files){string p=Path.Combine(mod,f);if(File.Exists(p))sources.Add(p);}if(sources.Count==0)throw new Exception("No profile files to back up.");string folder=Path.Combine(Home,DateTime.Now.ToString("yyyyMMdd-HHmmss")+"-"+Guid.NewGuid().ToString("N").Substring(0,6));Core.PrivateDir(folder);var rows=new List<Dictionary<string,object>>();foreach(string source in sources.OrderBy(x=>x)){string rel=source.Substring(mod.TrimEnd('\\').Length+1);Core.Under(source,mod);string target=Path.Combine(folder,"files",rel);Core.NoLinks(target,folder);Directory.CreateDirectory(Path.GetDirectoryName(target));string hash=Core.HashFile(source);File.Copy(source,target);if(hash!=Core.HashFile(target)||hash!=Core.HashFile(source))throw new Exception("Memory changed during backup. Backup was not completed.");rows.Add(new Dictionary<string,object>{{"path",rel},{"sha256",hash}});}Core.GameClosed();File.WriteAllText(Path.Combine(folder,"manifest.json"),Json.Write(new Dictionary<string,object>{{"format","PalcherBTW-memory-1"},{"created_utc",DateTime.UtcNow.ToString("o")},{"files",rows}}),new UTF8Encoding(false));return folder;}
 public static Plan PrepareRestore(string game,string folder){Core.GameClosed();Core.ValidateRoot(game);folder=Path.GetFullPath(folder);Core.NoLinks(Path.Combine(folder,"manifest.json"),folder);var m=Json.Read(File.ReadAllText(Path.Combine(folder,"manifest.json")));if(Json.Str(m,"format")!="PalcherBTW-memory-1")throw new Exception("This is not a helper memory backup.");var rows=((System.Collections.IEnumerable)m["files"]).Cast<object>().Select(x=>(Dictionary<string,object>)x).ToArray();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var p=new Plan{Game=Path.GetFullPath(game)};foreach(var r in rows){string rel=Json.Str(r,"path");if(!Allowed(rel)||rel.Contains(":")||rel.Split('\\','/').Any(x=>x==".."||x=="")||!seen.Add(rel))throw new Exception("Invalid path in memory backup.");string src=Path.Combine(folder,"files",rel);Core.NoLinks(src,folder);if(Core.HashFile(src)!=Json.Str(r,"sha256"))throw new Exception("Backup file is damaged: "+rel);Core.Add(p,Path.Combine(Core.Mod(game),rel),null,src);}foreach(string d in new[]{@"data\memory","sessions"}){string dir=Path.Combine(Core.Mod(game),d);if(!Directory.Exists(dir))continue;foreach(string f in Walk(dir)){string rel=f.Substring(Core.Mod(game).TrimEnd('\\').Length+1);if(!seen.Contains(rel)){Core.NoLinks(f,game);p.Changes.Add(new Change{Target=f,BeforeHash=Core.HashFile(f),AfterHash="",Existed=true,Delete=true});}}}p.Summary.Add("Restore memory files, characters and story templates from the selected backup.");return p;}
}
}
